def find_max_average(nums, k):
    n = len(nums)
    max_sum = float("-inf")
    for start in range(n - k + 1):
        window_sum = 0
        for i in range(start, start + k):
            window_sum += nums[i]                                       # re-add every element of this window from scratch
        max_sum = max(max_sum, window_sum)
    return max_sum / k


if __name__ == "__main__":
    print(f"{find_max_average([1, 12, -5, -6, 50, 3], 4):.5f}")

