def find_max_average(nums, k):
    window_sum = sum(nums[:k])                                        # sum of the very first window, built once
    max_sum = window_sum
    for i in range(k, len(nums)):
        window_sum += nums[i] - nums[i - k]                              # add the entering element, remove the one leaving
        max_sum = max(max_sum, window_sum)
    return max_sum / k


if __name__ == "__main__":
    print(f"{find_max_average([1, 12, -5, -6, 50, 3], 4):.5f}")

